 try{
  for(const r of state.reports){if(!r.htmlSaved)continue;const html=await readHtml(r.id);if(html){total+=html.length;if(total>175*1024*1024)throw Error('Archived HTML exceeds the 175 MB single-backup safety limit. Keep original HTML files and export your profile separately.');archivedHtml[r.id]=html}}
  const data={type:'midir-companion-backup',version:2,data:state,archivedHtml,trainingExtras:{herbs:window.MIDIR_HERBS?.exportState(),pig:window.MIDIR_PIG?.exportState(),reforge:window.MIDIR_REFORGE?.exportState(),bb:window.MIDIR_BB?.exportState()}};download(new Blob([JSON.stringify(data)],{type:'application/json'}),'midir-companion-full-backup.json');message('Full backup created: '+state.reports.length+' reports and '+Object.keys(archivedHtml).length+' HTML archives. Keep this file in a safe location.');
 }catch(err){message('Full backup unavailable: '+err.message)}
