  if(now.deathCount!==null&&was.deathCount!==null&&(now.deathCount<was.deathCount||(now.deathCount===0&&was.deathCount===0&&verifiedBossClear(r)&&verifiedBossClear(previous)))){const held=now.deathCount===0&&was.deathCount===0;events.push({...common,type:'fewer-deaths',title:held?'Fewer Falls · Zero maintained!':'Fewer falls!',detail:held?`Another verified deathless ${r.encounter} clear. You kept your falls at zero.`:`You reduced recorded deaths from ${was.deathCount} to ${now.deathCount} against ${r.encounter}.`,magnitude:held?100:100*(was.deathCount-now.deathCount)/Math.max(1,was.deathCount),delta:was.deathCount-now.deathCount,evidence:held?'verified clears and death event counts':'death event counts'})}
