   events.push({...common,type:'against-all-odds',title:'Against All Odds!',detail:`Your party finished ${a.name} after at least two other fighters exhausted their normal revives.`,magnitude:40,evidence:'verified Bri gate clear, identified non-Harmonic Saint teammates and two in-gate recorded deaths each'});
