   const clears=earlier.filter(x=>x.a.clear&&['bri-g1','bri-g2','bri-g3'].includes(x.a.group)&&x.r.targetScope===r.targetScope&&x.p.name===p.name).map(x=>({group:x.a.group,seconds:x.a.duration,reportId:x.r.id}));
