    eligible.set(r.id,{group:a.group,seconds:a.duration,reportId:r.id});
    if(eligible.size>=5&&!state.metricMilestones.some(x=>x.type==='clockwork'&&x.player===p.name))events.push({...common,type:'clockwork',title:'Clockwork!',detail:'Five distinct verified Bri Leitt gate fights, each finished in less than half that gate’s mission time allowance. Fast fights, consistent results.',magnitude:5,evidence:'five distinct verified gate boss-combat intervals, each below half of 20/30-minute mission allowance; not total mission duration'});
