rotation=function(){if(ARCANA_PAGES[state.arcana])return arcanaPage(state.arcana);return arcOriginalRotation()};
function arcanaPage(key){const a=ARCANA_PAGES[key];const skills=a.skills.length?a.skills.map(n=>`<span class="arc-skill">${esc(n)}</span>`).join(''):'<span class="hint">Skill-specific cards awaiting verified references; no fabricated skill names.</span>';
let drill='';
if(key==='fa')drill=`<div class="herb-field" id="herb-field" aria-label="Herb collection field"><button class="herb" data-act="arc-herb" style="left:${arcRuntime.herbX}%;top:${arcRuntime.herbY}%" aria-label="Collect herb">🌿</button></div><p class="stat">${arcRuntime.herbs} herbs collected</p>${arcRuntime.herbs>=5?'<p class="herb-praise">You\'re doing great!</p>':''}${arcRuntime.herbs>=10?'<p class="herb-praise">Forbidden Alchemists are great at crunching numbers, so since you did that already I thought I\'d remind you not to take this so seriously and have some fun once in a while!</p>':''}<p class="hint">Each herb moves to a new location. There is no time limit, completion requirement, or grade.</p>${buttons([['Reset herbs','arc-herb-reset']])}`;
else if(key==='sg')drill=sgWorkshop();
else if(key==='mp')drill=`<div class="arc-cue">${arcRuntime.ordinary>arcRuntime.weaves?'Cutting Chorus opportunity — weave when appropriate':'Use an ordinary skill, then look for an available Cutting Chorus window.'}</div><div class="button-row"><button data-act="arc-main" class="primary">Other skill</button><button data-act="arc-chorus">Cutting Chorus</button></div><p>Other skills: <strong>${arcRuntime.ordinary}</strong> · Chorus insertions: <strong>${arcRuntime.weaves}</strong></p><p class="hint">Practice the rhythm, not a fixed numerical score. Availability and animation behavior depend on the real game.</p>${buttons([['Reset practice','arc-weave-reset']])}`;
else {const scene=a.prompts[arcRuntime.scenario%a.prompts.length];drill=`<p class="hint">Scenario ${arcRuntime.scenario%a.prompts.length+1} of ${a.prompts.length}</p><div class="arc-cue">${esc(scene[0])}</div>${buttons([[scene[1],'arc-choice:0','primary'],[scene[2],'arc-choice:1']])}${arcRuntime.follow?`<p class="lesson">${esc(arcRuntime.follow)}</p>`:''}${buttons([['Next situation','arc-next']])}<p class="hint">These are decision rehearsal prompts; the Companion does not judge which approach you choose.</p>`;}
return `<h2>${esc(a.name)} · Rotation Lab</h2><p class="muted">${esc(a.subtitle)}. An exploratory page, not an authoritative rotation guide.</p><div class="cols"><div>${pane(a.drill,`<p>${esc(a.description)}</p>${drill}`)}</div><div>${pane('Skill reference · preliminary',`<div class="arc-skills">${skills}</div><p class="hint">Listed skills are sourced from Mabinogi World Wiki category pages or Nexon where available. Newer Arcana skill mappings may be incomplete; gameplay timings have not been validated.</p>`)}${pane('Training philosophy','<p>Teach what you control. Prepare for what you cannot. Celebrate what you accomplish together.</p><p class="hint">No forced perfect rotation, no measured DPS claim, no penalties for choosing a different response.</p>')}</div></div>`;
}
