action=function(s){if(s.startsWith('hub:')){if(typeof musicBuffSession!=='undefined'&&musicBuffSession)musicBuffEnd();rotationView=s.slice(4)==='home'?'reference':s.slice(4);stopTimers();return render()}if(s==='ag-random'){agPositionRandom();return render()}if(s==='ag-clear'){agPosition.fields=[];agPosition.last='Fields cleared';agPositionPaint();return}if(s==='ag-fire'){agPositionFire();return}if(s==='pos-random'){randomizeSandbox();return render()}if(s==='pos-reset'){positionSandbox.eliminated.clear();positionSandbox.last='All targets restored';return posPaint()}if(s==='pos-fire'){const p=positionSandbox;if(p.busy)return;p.busy=true;p.eliminated=new Set(posHits());p.last=`Eliminated ${p.eliminated.size} target${p.eliminated.size===1?'':'s'}! Move or adjust your next attack.`;posPaint();$('position-arena')?.classList.add('position-fired');setTimeout(()=>{p.busy=false;$('position-arena')?.classList.remove('position-fired')},700);return}return rotationActionOriginal(s)};
