 if(kind==='brawler')return `<svg viewBox="0 0 540 220" role="img" aria-label="Cartoon brawler practicing on a strawman"><g id="craft-character" transform="translate(146 122)"><circle cx="0" cy="-42" r="20" fill="#f4c7a0" stroke="#db9b73" stroke-width="2"/><path d="M-10 -18L-20 38M10 -18L20 38" fill="none" stroke="#e3edf8" stroke-width="11" stroke-linecap="round"/><path class="arm-left" d="M-14 6L16 12" fill="none" stroke="#e3edf8" stroke-width="11" stroke-linecap="round"/><path class="arm-right" d="M14 6L46 12" fill="none" stroke="#e3edf8" stroke-width="11" stroke-linecap="round"/><path class="leg-left" d="M-20 38L0 72" fill="none" stroke="#d4e4fa" stroke-width="11" stroke-linecap="round"/><path class="leg-right" d="M20 38L40 72" fill="none" stroke="#d4e4fa" stroke-width="11" stroke-linecap="round"/><path d="M-24 -20L24 -20L31 42L-31 42Z" fill="#bf552d"/></g><g id="craft-projectile" opacity="0"><path d="M248 94Q282 78 318 92" fill="none" stroke="#ffd38f" stroke-width="9" stroke-linecap="round"/></g>${strawClose}</svg>`;
